import * as React from "react";

/**
 * IconKorona — React + TypeScript component that renders the provided SVG
 * and lets you control colors, size, accessibility, and attach events.
 *
 * Quick use:
 *   <IconKorona width={240} accentFill="#ffd166" primaryFill="#ffffff" />
 *
 * Data-driven use:
 *   <IconKorona data={{ theme: "dark", status: "gold" }} />
 */
export type EmblemData = {
  /** Arbitrary keys you might pass from your app/state/store */
  theme?: "light" | "dark";
  status?: "gold" | "silver" | "white";
  // You can extend this freely; the component maps some sensible defaults.
  primaryFill?: string;
  accentFill?: string;
};

export interface IconKoronaProps
  extends React.SVGProps<SVGSVGElement> {
  /** Width/height accept numbers (px) or CSS strings (e.g. "2rem", "100%") */
  width?: number | string;
  height?: number | string;
  /** Fallback fill colors (can be overridden by `data` too) */
  primaryFill?: string; // maps to .cls-1 (white parts)
  accentFill?: string;  // maps to .cls-2 (gold parts)
  /**
   * If true, hides from screen readers (purely decorative). Otherwise, provide
   * `title`/`aria-label` for accessibility.
   */
  decorative?: boolean;
  /** Optional object to drive colors / theming dynamically */
  data?: EmblemData;
}

const resolveColors = (
  props: Pick<IconKoronaProps, "primaryFill" | "accentFill" | "data">
) => {
  // Defaults (from the original SVG)
  let primary = props.primaryFill ?? "#fff";
  let accent = props.accentFill ?? "#edc363";

  // Map simple data states to colors; you can tweak/extend as needed
  if (props.data) {
    const { theme, status, primaryFill, accentFill } = props.data;
    if (primaryFill) primary = primaryFill;
    if (accentFill) accent = accentFill;

    if (theme === "dark" && primary === "#fff") {
      // On dark backgrounds, keep white but you might prefer a softer tone
      primary = "#f8fafc"; // slate-50
    }

    if (status === "silver") accent = "#c0c0c0";
    if (status === "white") accent = "#ffffff";
    if (status === "gold") accent = "#edc363"; // ensure gold
  }

  return { primary, accent };
};

const toCssSize = (v: number | string | undefined, fallback: string) =>
  v === undefined ? fallback : typeof v === "number" ? `${v}px` : v;

